{
  "understanding": {
    "purpose": "Show league standings after 28 matches, with each team's results, goal record and points available for comparison.",
    "reading": "Readers scan down the team names and points to follow the standings, then across a row to understand a team's record. The narrow viewport leaves little spare width after keeping every word and number intact.",
    "groups": [
      "Team identifies each row and needs substantially more space than the statistical columns.",
      "P, W, D and L describe matches played and results.",
      "GF, GA and GD describe goals scored, conceded and their difference.",
      "Pts is the points total and a primary value for comparing standings."
    ],
    "keep_intact": [
      "Individual words in team names, especially Harborough and Wanderers.",
      "All numeric values, including signs on goal differences.",
      "Short column headers."
    ],
    "may_wrap": [
      "Team names may wrap at spaces; longer names can use multiple lines while the statistics remain on one line."
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [127, 42, 39, 34, 39, 43, 45, 52, 48],
      "idea": "Give all spare width to team names to reduce wrapping where possible, while keeping each statistic at its minimum intact width."
    },
    {
      "name": "B",
      "widths": [118, 43, 41, 38, 41, 43, 45, 52, 48],
      "idea": "Use the spare width to make the match-result columns more even, accepting more wrapping in team names."
    },
    {
      "name": "C",
      "widths": [118, 42, 39, 34, 39, 45, 47, 55, 50],
      "idea": "Give the goal and points columns extra breathing room to emphasize comparison of those values, while allowing team names to wrap."
    }
  ]
}
